// Both tables per locale; English is canonical and the fallback per key.
const LOCALES: Readonly<Record<string, readonly [Record<string, string>, Record<string, string>]>> = {
  en: [copy, changeCopy], uk: [copy_uk, changeCopy_uk], de: [copy_de, changeCopy_de], fr: [copy_fr, changeCopy_fr], pl: [copy_pl, changeCopy_pl], "pt-BR": [copy_ptBR, changeCopy_ptBR], pt: [copy_pt, changeCopy_pt], it: [copy_it, changeCopy_it], es: [copy_es, changeCopy_es], "zh-CN": [copy_zhCN, changeCopy_zhCN], bg: [copy_bg, changeCopy_bg], ar: [copy_ar, changeCopy_ar],
};

const interpolate = (value: string, values?: Record<string, string | number>): string => value.replace(/\{(\w+)\}/g, (_, key: string) => String(values?.[key] ?? ""));
export const gitlabHostingText = (locale: string, key: string, values?: Record<string, string | number>): string => {
  const [own, ownChange] = LOCALES[locale] ?? LOCALES[locale.split("-")[0]!] ?? LOCALES.en!;
  const value = ownChange[key] ?? own[key] ?? changeCopy[key] ?? copy[key] ?? key;
  return interpolate(value, values);
};
